import { APP_ROLES, type SecretField } from '../core/config/index.js';

/** Chart của boilerplate và hai file sinh từ metadata secret (spec SP7 §6.4, §12.5). */
export const CHART_DIR = 'deploy/helm/saas-app';
export const SECRET_ENV_FILE = `${CHART_DIR}/files/secret-env.json`;
export const VALUES_SCHEMA_FILE = `${CHART_DIR}/values.schema.json`;
/** Định dạng ổn định của hai file (nằm trong .prettierignore: src không được import prettier, luật not-to-dev-dep). */
const JSON_INDENT = 2;
const SECRET_ENV_NAME_DESCRIPTION =
  'Generated by pnpm chart:secrets from .meta(secretMeta(...)) on the config schemas; do not edit by hand';

export type ChartSecretFiles = { secretEnv: string; valuesSchema: string };

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);
const stringify = (v: unknown): string =>
  `${JSON.stringify(v, null, JSON_INDENT)}\n`;

/**
 * Hàm thuần: allowlist vai trò (files/secret-env.json) và `$defs.secretEnvName` của values.schema.json. Chỉ thay đúng
 * một khoá của schema; thứ tự khoá còn lại giữ nguyên (spread giữ vị trí của khoá đã có), nên chạy lại cho cùng byte.
 */
export function renderChartSecrets(
  fields: readonly SecretField[],
  currentSchema: string,
): ChartSecretFiles {
  const sorted = [...fields].sort((a, b) => a.env.localeCompare(b.env));
  const seen = new Set<string>();
  for (const f of sorted) {
    if (seen.has(f.env))
      throw new Error(`${f.env} is declared as a secret twice`);
    seen.add(f.env);
  }
  const schema: unknown = JSON.parse(currentSchema);
  if (!isRecord(schema) || !isRecord(schema.$defs))
    throw new Error(
      `${VALUES_SCHEMA_FILE} must be a JSON object with a $defs object`,
    );
  const secretEnv = Object.fromEntries(
    sorted.map((f) => [f.env, APP_ROLES.filter((r) => f.roles.includes(r))]),
  );
  const next = {
    ...schema,
    $defs: {
      ...schema.$defs,
      secretEnvName: {
        description: SECRET_ENV_NAME_DESCRIPTION,
        enum: sorted.map((f) => f.env),
      },
    },
  };
  return { secretEnv: stringify(secretEnv), valuesSchema: stringify(next) };
}

export function chartSecretsDrift(
  expected: ChartSecretFiles,
  actual: ChartSecretFiles,
): string[] {
  return [
    ...(expected.secretEnv === actual.secretEnv ? [] : [SECRET_ENV_FILE]),
    ...(expected.valuesSchema === actual.valuesSchema
      ? []
      : [VALUES_SCHEMA_FILE]),
  ];
}
